{
  "tool": "GetMcpServerStatus",
  "description": "The runtime status of the user's installed MCP servers (connected / needsAuth / error, per account). Pass server_id (the server identifier, NEVER a display name) for one server; omit it to list everything. Use this to see which connectors still need authentication, to find the identifier a lifecycle tool needs — the same one GetDynamicTools and CallDynamicTool address — or to check a connector after installing or authenticating. Read-only and never needs the user's permission.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "server_id": {
        "type": "string",
        "description": "Optional. One server to report on. The server identifier shown by GetMcpServerStatus — the same identifier GetDynamicTools and CallDynamicTool address, e.g. \"dashboard-team-1-Slack\". Never a display name. Omit to list every installed server."
      }
    }
  }
}

{
  "tool": "SearchPlugins",
  "description": "Search the plugins the user could install (or already has): marketplace plugins bundling connectors and skills. Say what you're looking for in natural language and results come back ranked by relevance, each with its STABLE plugin id, install state, and what it includes. Use this to discover a capability (Linear, Notion, writing Word documents, …) or to check whether a plugin is installed. Inspect one result with GetPlugin; connector runtime statuses (connected/needsAuth) live in GetMcpServerStatus. This is read-only and never needs the user's permission.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "query": {
        "type": "string",
        "description": "Optional. What you're looking for, in natural language (e.g. \"manage linear issues\" or \"write word documents\") — results come back ranked by relevance. Omit to list the whole catalog."
      }
    }
  }
}

{
  "tool": "TodoWrite",
  "description": "Your task queue: the durable list of everything the user has asked for, across all your parallel streams of work.\n\nWhen to use:\n- The moment a request arrives, record it as a todo before dispatching or starting it.\n- Update statuses in real time: in_progress when its work starts, completed the moment its result is delivered to the user, cancelled when the user drops it or changes their mind.\n- On every wake (a user message or a finished background task), reconcile the list first: what's running, what landed, what to dispatch next.\n\nStates and parallelism:\n- pending: not yet started. in_progress: actively being worked, by you or a background worker. completed: result delivered to the user. cancelled: no longer needed.\n- SEVERAL todos are normally in_progress at once — one per independent stream running in parallel (each dispatched worker, plus at most one thing you are doing inline). Never serialize independent streams just to keep a single one in_progress.\n- Keep the list current rather than perfect: cancel stale items instead of leaving them pending, and prune long-finished ones when the list gets noisy.\n\nSkip it for purely conversational replies and trivial one-step lookups you answer inline immediately.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "todos": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "description": "Unique identifier for the TODO item"
            },
            "content": {
              "type": "string",
              "description": "The description/content of the todo item"
            },
            "status": {
              "type": "string",
              "enum": [
                "pending",
                "in_progress",
                "completed",
                "cancelled"
              ],
              "description": "The current status of the TODO item"
            }
          },
          "required": [
            "id",
            "content",
            "status"
          ]
        },
        "minItems": 2,
        "description": "Array of TODO items to update or create"
      },
      "merge": {
        "type": "boolean",
        "description": "Whether to merge the todos with the existing todos. If true, the todos will be merged into the existing todos based on the id field. You can leave unchanged properties undefined. If false, the new todos will replace the existing todos."
      }
    },
    "required": [
      "todos",
      "merge"
    ]
  }
}
